from pypdf import PdfReader
import re
r=PdfReader('manuscript.pdf')
for i,p in enumerate(r.pages, 1):
    t=p.extract_text()
    hits=[line for line in t.splitlines() if re.search(r'code|github|seed|checkpoint|normaliz|decod|temperature|signific|validation|human|LoRA|GPT-4',line,re.I)]
    if hits:
        print('PAGE',i)
        print('\\n'.join(hits))
urls=set()
for p in r.pages:
    for a in p.get('/Annots',[]):
        a=a.get_object()
        if '/A' in a:
            u=a['/A'].get('/URI')
            if u: urls.add(str(u))
print('External links:', '\\n'.join(sorted(urls)))
PY"
